; view_done: frame rate on the text rows
#addr 0x8E00
view_done:
    ld   [views_lo], ac         ; views drawn
    add  1, ac
    ld   ac, [views_lo]
    bcc  vd_1
    ld   [views_hi], ac
    add  1, ac
    ld   ac, [views_hi]
vd_1:
    ld   RATE_COL, ac           ; "nn" views a second, from the frames since
    ld   ac, [CUR_COL]          ; the last view
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   [vticks], ac
    and  63, ac
    ld   ac, [tmp]
    ld   ac, x
    ld   FPS_T >> 8, y
    ld   [y,x], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   vd_2, [x]
    ld   LINK_HI, x
    ld   vd_2 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
vd_2:
    ld   [tmp], ac
    add  FPS_O & 0xFF, ac
    ld   ac, x
    ld   FPS_O >> 8, y
    ld   [y,x], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   vd_3, [x]
    ld   LINK_HI, x
    ld   vd_3 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
vd_3:
    ld   MODE_COL, ac           ; "DEMO WALK" or "YOU DRIVE"
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   s_demo, ac
    ld   ac, [R0]
    ld   [demo], ac
    bne  vd_4
    ld   s_you, ac
    ld   ac, [R0]
vd_4:
    ld   s_demo >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   vd_5, [x]
    ld   LINK_HI, x
    ld   vd_5 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
vd_5:
    ld   view_loop >> 8, y
    jmp  view_loop

; build: the DD and HT tables in the RAM (once, at start)
#addr 0x8F00
build:
    clr  ac                     ; DD: G into pages 1 and 3, H into 0, 2, 4
    ld   ac, [tmp]              ;   (lows at DDYL, highs at DDYH)
b_dd:
    ld   [tmp], x
    ld   GL >> 8, y
    ld   [y,x], ac
    ld   (DDYL >> 8) + 1, y
    ld   ac, [y,x]
    ld   (DDYL >> 8) + 3, y
    ld   ac, [y,x]
    ld   GH >> 8, y
    ld   [y,x], ac
    ld   (DDYH >> 8) + 1, y
    ld   ac, [y,x]
    ld   (DDYH >> 8) + 3, y
    ld   ac, [y,x]
    ld   DD_MAX & 0xFF, ac      ; H[0] = DD_MAX, H[l] = G[256 - l]
    ld   ac, [mA]
    ld   DD_MAX >> 8, ac
    ld   ac, [mB]
    ld   [tmp], ac
    beq  b_h
    xor  255, ac
    add  1, ac
    ld   ac, x
    ld   GL >> 8, y
    ld   [y,x], ac
    ld   ac, [mA]
    ld   GH >> 8, y
    ld   [y,x], ac
    ld   ac, [mB]
    ld   [tmp], x
b_h:
    ld   [mA], ac
    ld   (DDYL >> 8) + 0, y
    ld   ac, [y,x]
    ld   (DDYL >> 8) + 2, y
    ld   ac, [y,x]
    ld   (DDYL >> 8) + 4, y
    ld   ac, [y,x]
    ld   [mB], ac
    ld   (DDYH >> 8) + 0, y
    ld   ac, [y,x]
    ld   (DDYH >> 8) + 2, y
    ld   ac, [y,x]
    ld   (DDYH >> 8) + 4, y
    ld   ac, [y,x]
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    bne  b_dd
    ld   HT >> 8, ac            ; HT: HCH:HCL[v] entries of value v, v = 255
    ld   ac, [mDL]              ;   down to 0, from HT on
    clr  ac                     ;   (mDL = page, mDH = offset, mB = v,
    ld   ac, [mDH]              ;   mRH:mRL = entries left)
    ld   255, ac
    ld   ac, [mB]
b_v:
    ld   [mB], x
    ld   HCL >> 8, y
    ld   [y,x], ac
    ld   ac, [mRL]
    ld   HCH >> 8, y
    ld   [y,x], ac
    ld   ac, [mRH]
b_n:
    ld   [mRL], ac
    or   [mRH], ac
    beq  b_nx
    ld   [mDL], y
    ld   [mDH], x
    ld   [mB], ac
    ld   ac, [y,x]
    ld   [mDH], ac
    add  1, ac
    ld   ac, [mDH]
    bcc  b_c
    ld   [mDL], ac
    add  1, ac
    ld   ac, [mDL]
b_c:
    ld   [mRL], ac
    sub  1, ac
    ld   ac, [mRL]
    bcc  b_n
    ld   [mRH], ac
    sub  1, ac
    ld   ac, [mRH]
    bra  b_n
b_nx:
    ld   [mB], ac
    sub  1, ac
    ld   ac, [mB]
    bcc  b_v
    ld   built >> 8, y
    jmp  built

